  M 'RefreshFlowSequence'|Out-Null;M 'RefreshFlowPortVisualization'|Out-Null;M 'RefreshPortPanel' ([object[]]@($script))|Out-Null;Assert(($script.FlowInputPorts|Where-Object{$_.PortName-eq$width.PortName}).Count-eq1-and($script.FlowOutputPorts|Where-Object{$_.PortName-eq$adjusted.PortName}).Count-eq1) 'Dynamic ports are missing from the flow node';Assert(((F 'inputPortRows')|Where-Object{$_.PortName-eq$width.PortName}).Count-eq1-and((F 'outputPortRows')|Where-Object{$_.PortName-eq$adjusted.PortName}).Count-eq1) 'Dynamic ports are missing from the I/O task page'
