  $judge.SetInputBinding('Value',$script.ToolId,$adjusted.PortName);$judge.InputToolId=$script.ToolId;$judge.InputPortName=$adjusted.PortName;$judge.NumericLowerLimit=20;$judge.NumericUpperLimit=20;Assert((Run $judge).ResultCode-eq'OK') 'Named Number output did not drive NumericJudge';$text.SetInputBinding('String',$script.ToolId,$note.PortName);$text.Parameters.TextAssemblyTemplate='NOTE={String}';Assert((Run $text).ResultCode-eq'OK'-and(Out $text Text)-eq'NOTE=PART-42-OK') 'Named String output did not drive TextAssembly';$verdict.SetInputBinding('ResultCodeA',$script.ToolId,$resultPort.PortName);$verdict.Parameters.ResultLogicOperation='PassThrough';Assert((Run $verdict).ResultCode-eq'OK') 'Named ResultCode output did not drive result logic'

  $script.SetInputBinding($width.PortName,$image.ToolId,'SN');$typeError=M 'GetInputBindingConfigurationError' ([object[]]@($script,$script.GetInputBinding($width.PortName)));Assert($typeError-match'mismatch|Number|String') 'Dynamic port type mismatch was not diagnosed';Assert((RunFailure $script).Length-gt0) 'Dynamic Number input accepted a String value';$script.SetInputBinding($width.PortName,$image.ToolId,'Width')
