  (F 'FlowToolList').SelectedItem=$script;$copied=[int](M 'CopySelectedFlowToolsToClipboard');Assert($copied-eq1) 'Script copy command failed';$beforePaste=$flow.Count;$pasted=[int](M 'PasteFlowToolClipboard' ([object[]]@($flow.IndexOf($script)+1)));Assert($pasted-eq1-and$flow.Count-eq$beforePaste+1) 'Script paste failed';$copy=$flow|Where-Object{$_.Kind.ToString()-eq'CSharpDllScript'-and$_.ToolId-ne$script.ToolId-and$_.Parameters.ScriptInterfaceMembers.Count-eq12}|Select-Object -First 1;Assert($null-ne$copy-and(FindMember $copy.Parameters Adjusted).MemberId-eq$adjusted.MemberId) 'Script interface schema was not copied with stable member IDs'
  (F 'FlowToolList').SelectedItem=$script;M 'OpenScriptInterfaceButton_Click' ([object[]]@($null,$null))|Out-Null;$draftMembers=F 'scriptInterfaceDraftMembers';$draftAdjusted=$draftMembers|Where-Object{$_.Name-eq'Adjusted'}|Select-Object -First 1;(F 'ScriptInterfaceMemberListBox').SelectedItem=$draftAdjusted;(F 'ScriptInterfaceNameTextBox').Text='AdjustedRenamed';M 'ApplyScriptMemberButton_Click' ([object[]]@($null,$null))|Out-Null;M 'ApplyScriptInterfaceButton_Click' ([object[]]@($null,$null))|Out-Null;Assert((FindMember $script.Parameters AdjustedRenamed).PortName-eq$adjusted.PortName) 'Renaming changed the stable dynamic output port';M 'CloseScriptInterfaceButton_Click' ([object[]]@($null,$null))|Out-Null
